"use client";

import { cn } from "@/lib/utils";
import { useEffect, useRef } from "react";
import type { ComponentProps, ReactNode } from "react";

import styles from "./skeleton.module.css";

type CadencedShimmerProps = ComponentProps<"span"> & { active?: boolean };

const CadencedShimmer = ({
  active = true,
  children,
  className,
  ...props
}: CadencedShimmerProps) => {
  const ref = useRef<HTMLSpanElement>(null);
  useEffect(() => {
    const element = ref.current;

    if (!element || !active) {
      return () => {
        element?.classList.remove(styles.active);
      };
    }

    const media = window.matchMedia("(prefers-reduced-motion: reduce)");
    const root = document.documentElement;
    let visible = false;
    let running = false;
    let start: ReturnType<typeof setTimeout>;
    let finish: ReturnType<typeof setTimeout>;
    let repeat: ReturnType<typeof setInterval>;

    const stop = () => {
      running = false;
      clearTimeout(start);
      clearTimeout(finish);
      clearInterval(repeat);
      element.classList.remove(styles.active);
    };

    const burst = () => {
      clearTimeout(finish);
      element.classList.remove(styles.active);
      element.classList.add(styles.active);
      finish = setTimeout(() => {
        element.classList.remove(styles.active);
      }, 900);
    };

    const update = () => {
      const preference = root.dataset.ckReducedMotion;

      const reduced =
        preference === undefined ? media.matches : preference === "true";

      const shouldRun = visible && !document.hidden && !reduced;

      if (shouldRun === running) {
        return;
      }

      if (!shouldRun) {
        stop();

        return;
      }

      running = true;
      start = setTimeout(() => {
        burst();
        repeat = setInterval(burst, 4200);
      }, 550);
    };

    const intersection = new IntersectionObserver((entries) => {
      visible = entries[0]?.isIntersecting ?? false;
      update();
    });

    intersection.observe(element);
    const mutation = new MutationObserver(update);
    mutation.observe(root, {
      attributeFilter: ["data-ck-reduced-motion"],
      attributes: true,
    });
    media.addEventListener("change", update);
    document.addEventListener("visibilitychange", update);

    return () => {
      intersection.disconnect();
      mutation.disconnect();
      media.removeEventListener("change", update);
      document.removeEventListener("visibilitychange", update);
      stop();
    };
  }, [active]);

  if (!active) {
    return (
      <span className={className} {...props}>
        {children}
      </span>
    );
  }

  return (
    <span
      ref={ref}
      className={cn(
        "relative inline-block align-top",
        styles.cadenced,
        className
      )}
      {...props}
    >
      {children}
      <span aria-hidden="true" className={styles.cadencedSweep}>
        <span className={styles.highlight}>{children}</span>
      </span>
    </span>
  );
};

const ThinkingShimmer = ({
  message = "Thinking",
  className,
  ...props
}: Omit<CadencedShimmerProps, "children"> & { message?: ReactNode }) => (
  // eslint-disable-next-line shadcn/require-static-classes -- The caller may add classes to the typography.
  <CadencedShimmer {...props} className={cn(styles.thinking, className)}>
    {message}
  </CadencedShimmer>
);

export { CadencedShimmer, ThinkingShimmer };

export type { CadencedShimmerProps };

.themeScope[data-theme="light"] {
  color-scheme: light;
  --ck-palette-surface-surface: var(--color-light-app-background-surface);
  --ck-palette-ink-tertiary: var(--color-light-app-text-foreground-tertiary);
  --color-panel: var(--ck-palette-surface-surface);
  background: var(--ck-palette-surface-surface);
}
.themeScope[data-theme="dark"] {
  color-scheme: dark;
  --ck-palette-surface-surface: var(--color-dark-app-background-surface);
  --ck-palette-ink-tertiary: var(--color-dark-app-text-foreground-tertiary);
  --color-panel: var(--ck-palette-surface-surface);
  background: var(--ck-palette-surface-surface);
}
.bar {
  --ck-results-sweep-base: color-mix(
    in srgb,
    var(--color-description, var(--ck-palette-ink-tertiary)) 10%,
    transparent
  );
  --ck-results-sweep-highlight: color-mix(
    in srgb,
    var(--color-description, var(--ck-palette-ink-tertiary)) 16%,
    transparent
  );
  position: relative;
  overflow: hidden;
  border-radius: var(--radius-md);
  background-color: var(--ck-results-sweep-base);
}
.bar[data-size="sm"] {
  height: calc(var(--spacing) * 3);
}
.bar[data-size="md"] {
  height: calc(var(--spacing) * 3.5);
}
.bar[data-size="lg"] {
  height: calc(var(--spacing) * 4);
}
.bar[data-size="thumbnail"] {
  width: calc(var(--spacing) * 10);
  height: calc(var(--spacing) * 10);
  border-radius: var(--radius-lg);
  flex-shrink: 0;
}
.bar[data-size="fill"] {
  width: 100%;
  height: 100%;
  display: block;
}
.bar::before {
  content: "";
  pointer-events: none;
  position: absolute;
  inset: 0;
  background: linear-gradient(
    90deg,
    transparent,
    var(--ck-results-sweep-highlight),
    transparent
  );
  transform: translateX(-100%);
  animation: sweep 3s linear infinite;
  animation-play-state: var(--ck-decoration-playback, running);
  animation-delay: var(--ck-results-sweep-delay, 0s);
}
.bar[data-variant="standard"],
.bar[data-variant="project"]::before {
  background-image: linear-gradient(
    90deg,
    var(--ck-results-sweep-base),
    var(--ck-results-sweep-highlight),
    var(--ck-results-sweep-base)
  );
}
.bar[data-variant="standard"] {
  animation: standard-sweep 3s linear infinite;
  animation-play-state: var(--ck-decoration-playback, running);
  background-size: 1000px 100%;
}
.bar[data-variant="standard"]::before {
  content: none;
  animation: none;
}
.bar[data-variant="edge-to-edge"] {
  border-radius: 0;
}
.bar[data-variant="conversation-followup"] {
  --ck-results-sweep-base: var(--ck-palette-surface-surface);
  --ck-results-sweep-highlight: color-mix(
    in srgb,
    var(--color-description, var(--ck-palette-ink-tertiary)) 16%,
    var(--ck-palette-surface-surface)
  );
  width: calc(var(--spacing) * 40);
  height: calc(var(--spacing) * 10);
  border-radius: var(--radius-pill, 9999px);
  border: 1px solid var(--color-border);
  box-shadow: var(--shadow-sm);
  flex-shrink: 0;
}
.bar[style*="--ck-sweep-width"] {
  width: var(--ck-sweep-width);
}
.bar[data-variant="project"] {
  background-color: transparent;
}
.bar[data-variant="project"]::before {
  width: 300%;
  right: auto;
  transform: translateX(0);
  animation: project 2s ease-in-out infinite alternate-reverse;
  animation-play-state: var(--ck-decoration-playback, running);
}
.bar[data-ck-reduced-motion="true"],
.bar[data-ck-reduced-motion="true"]::before,
:global(:root[data-ck-reduced-motion="true"]) .bar,
:global(:root[data-ck-reduced-motion="true"]) .bar::before {
  animation: none;
}
:global(:root[data-ck-reduced-motion="true"])
  .bar:is([data-variant="standard"], [data-variant="conversation-followup"]) {
  background: var(--ck-results-sweep-highlight);
}
@media (prefers-reduced-motion: reduce) {
  :global(:root:not([data-ck-reduced-motion])) .bar,
  :global(:root:not([data-ck-reduced-motion])) .bar::before {
    animation: none;
  }
  :global(:root:not([data-ck-reduced-motion]))
    .bar:is([data-variant="standard"], [data-variant="conversation-followup"]) {
    background: var(--ck-results-sweep-highlight);
  }
}
@keyframes sweep {
  to {
    transform: translateX(100%);
  }
}
@keyframes standard-sweep {
  from {
    background-position: -1000px 0;
  }
  to {
    background-position: 1000px 0;
  }
}
@keyframes project {
  from {
    transform: translateX(-66.67%);
  }
  to {
    transform: translateX(0);
  }
}
.placeholder {
  overflow: hidden;
}
.placeholder[data-animate] {
  --ck-placeholder-base: var(--ck-palette-surface-surface);
  --ck-placeholder-peak: light-dark(
    color-mix(
      in srgb,
      var(--color-description, var(--ck-palette-ink-tertiary)) 7%,
      var(--ck-palette-surface-surface)
    ),
    color-mix(
      in srgb,
      var(--color-description, var(--ck-palette-ink-tertiary)) 14%,
      var(--ck-palette-surface-surface)
    )
  );
  background-color: var(--ck-placeholder-base);
  position: relative;
}
.placeholder[data-animate]:where([data-theme="light"]) {
  --ck-placeholder-peak: color-mix(
    in srgb,
    var(--color-description, var(--ck-palette-ink-tertiary)) 7%,
    var(--ck-palette-surface-surface)
  );
}
.placeholder[data-animate]:where([data-theme="dark"]) {
  --ck-placeholder-peak: color-mix(
    in srgb,
    var(--color-description, var(--ck-palette-ink-tertiary)) 14%,
    var(--ck-palette-surface-surface)
  );
}
.placeholder[data-animate]::before {
  content: "";
  position: absolute;
  inset: 0;
  background: var(--ck-placeholder-peak);
  opacity: 0;
  animation: pulse 3s ease-in-out infinite;
  animation-play-state: var(--ck-decoration-playback, running);
}
:global(:root[data-ck-reduced-motion="true"])
  .placeholder[data-animate]::before {
  animation: none;
}
@media (prefers-reduced-motion: reduce) {
  :global(:root:not([data-ck-reduced-motion]))
    .placeholder[data-animate]::before {
    animation: none;
  }
}
@keyframes pulse {
  50% {
    opacity: 0.5;
  }
}
.thinking {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  user-select: none;
}
:where(.cadenced) {
  --ck-loading-sweep-foreground: initial;
  --ck-loading-sweep-base: initial;
  --ck-loading-sweep-highlight: initial;
}
.cadenced {
  --ck-sweep-text-secondary: var(
    --ck-loading-sweep-base,
    color-mix(
      in srgb,
      var(--ck-loading-sweep-foreground, var(--ck-palette-ink-tertiary)) 55%,
      transparent
    )
  );
  --ck-sweep-contrast: var(--ck-loading-sweep-highlight, var(--ck-palette-ink));
  -webkit-text-fill-color: currentColor;
}
.cadenced,
.cadenced * {
  color: var(--ck-sweep-text-secondary) !important;
}
.cadenced .highlight,
.cadenced .highlight * {
  color: var(--ck-sweep-contrast) !important;
}
.cadencedSweep {
  width: 100%;
  text-overflow: inherit;
  pointer-events: none;
  position: absolute;
  inset: 0 auto 0 0;
  overflow: hidden;
  transform: translateX(-50%);
  mask-image: linear-gradient(
    90deg,
    transparent 0%,
    var(--ck-mask) 22% 32%,
    transparent 52% 100%
  );
}
.highlight {
  width: 100%;
  text-overflow: inherit;
  -webkit-text-fill-color: currentColor;
  display: block;
  overflow: hidden;
  transform: translateX(50%);
}
.active .cadencedSweep,
.active .highlight {
  animation-duration: 0.9s;
  animation-timing-function: steps(44, end);
  animation-iteration-count: 1;
}
.active .cadencedSweep {
  animation-name: cadenceSweep;
}
.active .highlight {
  animation-name: cadenceHighlight;
}
@media (prefers-reduced-motion: reduce) {
  .active .cadencedSweep,
  .active .highlight {
    animation: none;
  }
}
@keyframes cadenceSweep {
  from {
    transform: translateX(-50%);
  }
  to {
    transform: translateX(130%);
  }
}
@keyframes cadenceHighlight {
  from {
    transform: translateX(50%);
  }
  to {
    transform: translateX(-130%);
  }
}

"use client";

import { useReducedMotion } from "@/lib/reduced-motion";
import { cn } from "@/lib/utils";
import type { ComponentProps, CSSProperties, ElementType } from "react";

import styles from "@/components/skeleton/skeleton.module.css";

// Widths come from seedrandom's ARC4 generator.
/* eslint-disable eslint/no-bitwise, unicorn/prefer-code-point */
const seededRandom = (seed: string) => {
  const key: number[] = [];
  let smear = 0;

  for (let index = 0; index < seed.length; index += 1) {
    const slot = index & 255;
    smear ^= (key[slot] ?? 0) * 19;
    key[slot] = (smear + seed.charCodeAt(index)) & 255;
  }

  const state = Array.from({ length: 256 }, (_, index) => index);
  let i = 0;
  let j = 0;

  for (let index = 0; index < 256; index += 1) {
    j = (j + state[index] + (key[index % key.length] ?? 0)) & 255;
    [state[index], state[j]] = [state[j], state[index]];
  }

  j = 0;

  const generate = (count: number) => {
    let result = 0;

    for (let index = 0; index < count; index += 1) {
      i = (i + 1) & 255;
      const value = state[i];
      j = (j + value) & 255;
      state[i] = state[j];
      state[j] = value;
      result = result * 256 + state[(state[i] + value) & 255];
    }

    return result;
  };

  generate(256);

  return () => {
    let value = generate(6);
    let denominator = 256 ** 6;
    let extra = 0;

    while (value < 2 ** 52) {
      value = (value + extra) * 256;
      denominator *= 256;
      extra = generate(1);
    }

    while (value >= 2 ** 53) {
      value /= 2;
      denominator /= 2;
      extra >>>= 1;
    }

    return (value + extra) / denominator;
  };
};

/* eslint-enable eslint/no-bitwise, unicorn/prefer-code-point */

const clampWidth = (value: number) => Math.max(1, Math.min(100, value));

type ShimmerSize = "sm" | "md" | "lg" | "thumbnail" | "fill";

type ShimmerVariant =
  | "standard"
  | "project"
  | "edge-to-edge"
  | "conversation-followup";

type BarProps = ComponentProps<"div"> & {
  as?: ElementType;
  animate?: boolean;
  delayMs?: number;
  size?: ShimmerSize;
  variant?: ShimmerVariant;
  widthPercent?: number;
};

const LoadingResultsShimmer = ({
  as: Element = "div",
  animate = true,
  className,
  delayMs,
  size = "md",
  style,
  variant,
  widthPercent,
  ...props
}: BarProps) => {
  const reducedMotion = useReducedMotion();

  const barStyle: CSSProperties & {
    "--ck-results-sweep-delay"?: string;
    "--ck-sweep-width"?: string;
  } = {
    ...style,
    "--ck-sweep-width":
      widthPercent === undefined ? undefined : `${clampWidth(widthPercent)}%`,
    "--ck-results-sweep-delay":
      delayMs === undefined ? undefined : `${delayMs}ms`,
  };

  return (
    <Element
      {...props}
      aria-hidden="true"
      className={cn(styles.bar, className)}
      data-size={size}
      data-variant={variant}
      data-ck-reduced-motion={!animate || reducedMotion || undefined}
      style={barStyle}
    />
  );
};

type LinesProps = ComponentProps<"div"> &
  Pick<BarProps, "animate" | "size" | "variant"> & {
    lines?: number;
    minWidth?: number;
    maxWidth?: number;
    seed?: string;
    lineClassName?: string;
  };

const LoadingResultsShimmerLines = ({
  animate = true,
  className,
  lineClassName,
  lines = 3,
  minWidth = 55,
  maxWidth = 100,
  seed = "shimmer-lines",
  size = "md",
  variant,
  ...props
}: LinesProps) => {
  const min = clampWidth(Math.min(minWidth, maxWidth));
  const max = clampWidth(Math.max(minWidth, maxWidth));
  const random = seededRandom(`${seed}:${lines}:${min}:${max}`);

  const widths = Array.from(
    { length: Math.max(0, lines) },
    () => min + random() * (max - min)
  );

  return (
    <div
      {...props}
      className={cn("flex w-full flex-col items-start gap-2", className)}
    >
      {widths.map((width, index) => (
        <LoadingResultsShimmer
          key={index}
          animate={animate}
          className={lineClassName}
          delayMs={-index * 120}
          size={size}
          variant={variant}
          widthPercent={width}
        />
      ))}
    </div>
  );
};

type PlaceholderProps = ComponentProps<"div"> & {
  animate?: boolean;
  variant?: "default" | "solid" | "prominent";
};

const LoadingPlaceholder = ({
  animate = true,
  className,
  variant = "default",
  ...props
}: PlaceholderProps) => (
  <div
    {...props}
    data-loading-indicator=""
    data-animate={(variant === "default" && animate) || undefined}
    data-variant={variant}
    className={cn(
      styles.placeholder,
      variant === "solid" && "bg-panel-secondary",
      variant === "prominent" && "bg-text/10",
      variant === "prominent" && animate && "motion-safe:animate-pulse",
      className
    )}
  />
);

export {
  LoadingPlaceholder,
  LoadingResultsShimmer,
  LoadingResultsShimmerLines,
};

export type { BarProps, LinesProps, PlaceholderProps };
